/// <summary>
/// find
/// </summary>
public static DemoCompanyInfo find(RecId _recId, boolean _forUpdate = false)
{
    DemoCompanyInfo demoCompanyInfo;

    demoCompanyInfo.selectForUpdate(_forUpdate);

    select firstonly demoCompanyInfo
        where demoCompanyInfo.RecId == _recId;

    return demoCompanyInfo;
}
